SELECT ?point ?tsid ?room WHERE {
  ?room a brick:Zone .
  FILTER (regex(str(?room), "Perimeter_(mid|top)_ZN_1", "i"))
  ?point brick:hasSuperclass* brick:Zone .  # skip
}

SELECT ?room ?point WHERE {
  ?room a brick:PerimeterZone .
  FILTER (regex(str(?room), "mid_ZN_1|top_ZN_1", "i"))
  ?point brick:isPointOf ?room .
}

SELECT ?zone ?point ?pttype ?tsid WHERE {
  ?zone a brick:Zone .
  FILTER (regex(str(?zone), "Zone_F2_Z02|Zone_F3_Z02"))
  ?point ?p ?zone .
  ?point a ?pttype .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid }
  ?point ref:hasExternalReference ?ext .
  FILTER (regex(str(?pttype), "Occupancy", "i"))
}

SELECT ?zone ?point WHERE {
  FILTER regex(str(?zone), "Zone_F2_Z02|Zone_F3_Z02")
  { ?point brick:hasSubclass* ?zone } UNION { ?zone brick:hasSubclass* ?point } UNION { ?x ?p ?zone ; }
}

SELECT ?point ?tsid ?ext WHERE {
  ?point a brick:OccupancySensor.
  FILTER (regex(str(?point), "Zone_F2_Z02|Zone_F3_Z02"))
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid }
  OPTIONAL { ?point ref:hasExternalReference ?ext }
}

